#!/bin/sh
# GENERATED by `fabricx generate`. Attach the host-facing ports of leaf3 to their VLAN bridges.
# Runs after containerlab has wired the links (clab `exec`). That can happen before setup.sh (started by the
# container's own command) has built the bridges, so wait for each bridge, at most 30 s.
set -e
# --- host port eth3 -> h5
for i in $(seq 60); do ip link show br30 >/dev/null 2>&1 && break; sleep 0.5; done
ip link set eth3 master br30
ip link set eth3 up
